.pj {display:flex;width:14px;height:14px;flex-shrink:0;align-items:center;justify-content:center;border-radius:var(--radius-sm);font-family:var(--font-mono);font-size:var(--text-plan-chip);line-height:1;font-weight:var(--font-weight-semibold);letter-spacing:var(--tracking-tighter);user-select:none}
.pj[data-color="chart-1"] {background:color-mix(in srgb,var(--color-chart-1) 15%,transparent);color:var(--color-chart-1)}
.pj[data-color="chart-2"] {background:color-mix(in srgb,var(--color-chart-2) 15%,transparent);color:var(--color-chart-2)}
.pj[data-color="chart-3"] {background:color-mix(in srgb,var(--color-chart-3) 15%,transparent);color:var(--color-chart-3)}
.pj[data-color="chart-4"] {background:color-mix(in srgb,var(--color-chart-4) 15%,transparent);color:var(--color-chart-4)}
.pj[data-color="chart-5"] {background:color-mix(in srgb,var(--color-chart-5) 15%,transparent);color:var(--color-chart-5)}
.pj[data-color="chart-6"] {background:color-mix(in srgb,var(--color-chart-6) 15%,transparent);color:var(--color-chart-6)}
.pj[data-color="chart-7"] {background:color-mix(in srgb,var(--color-chart-7) 15%,transparent);color:var(--color-chart-7)}
.pj[data-color="chart-8"] {background:color-mix(in srgb,var(--color-chart-8) 15%,transparent);color:var(--color-chart-8)}
